  if (!value) return "";
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "medium",
    timeStyle: "short"
  }).format(new Date(value));
}

export function buildTicketNote(note) {
  return `FIELD NOTE
Context: ${note.context || ""}
Category: ${note.category || ""}
Priority: ${note.priority || ""}
Status: ${note.status || ""}
Created: ${formatDateTime(note.createdAt)}

Issue:
${note.issue || ""}

Checks performed:
${note.checks || ""}

Changes / actions taken:
${note.changes || ""}

Result:
${note.result || ""}

Follow-up / watch items:
${note.followUp || ""}

Tags:
${note.tags || ""}`;
}

export function buildClientSummary(note) {
  const summary = [note.issue, note.result].filter(Boolean).join(" ");

  return `Summary:
${summary}

Action taken:
${note.changes || ""}

Follow-up:
${note.followUp || ""}`;
}

export function buildExportText(notes) {
  return notes.map(buildTicketNote).join("\n\n---\n\n");
}
