{"call_id": "call_bMB0UwoWVTyHkkCrHKX71GsK", "changes": {"C:\Users\joshu_w0zb8cp\OneDrive - Dubbo Christian School\Documents\New project\src\app.js": {"content": "import { clearNotes, loadNotes, saveNotes } from "./storage.js";
import { buildClientSummary, buildExportText, buildTicketNote, formatDateTime } from "./formatters.js";

const contexts = ["Avance", "DCS", "PTS", "Personal Lab", "Other"];
const categories = ["Account", "Email", "OneDrive", "Printer", "Network", "Wi-Fi", "Device", "AV", "Security", "Medical Objects", "Backup", "Other"];
const priorities = ["Low", "Normal", "High", "Urgent"];
const statuses = ["Draft", "Complete", "Needs Follow-up"];
let notes = loadNotes();
let activeNoteId = "";
let activeSpeechField = null;
const $ = (id) => document.getElementById(id);
const fields = ["noteId", "context", "title", "category", "priority", "status", "manualLocation", "issue", "checks", "changes", "result", "followUp", "tags"].reduce((map, id) => ({ ...map, [id]: $(id) }), {});

function init() {
  fillSelect($("contextFilter"), ["All contexts", ...contexts]);
  fillSelect($("categoryFilter"), ["All categories", ...categories]);
  fillSelect($("statusFilter"), ["All statuses", ...statuses]);
  fillSelect($("priorityFilter"), ["All priorities", ...priorities]);
  fillSelect(fields.context, contexts);
  fillSelect(fields.category, categories);
  fillSelect(fields.priority, priorities);
  fillSelect(fields.status, statuses);
  bindEvents();
  setupSpeech();
  renderList();
}

function fillSelect(select, options) {
  select.innerHTML = options.map((option) => `<option value="${escapeHtml(option)}">${escapeHtml(option)}</option>`).join("");
}

function bindEvents() {
  $("newNoteBtn").addEventListener("click", newNote);
  $("newNoteTop").addEventListener("click", newNote);
  $("backFromForm").addEventListener("click", showList);
  $("backFromDetail").addEventListener("click", showList);
  $("saveDraftBtn").addEventListener("click", () => saveForm("Draft"));
  $("markCompleteBtn").addEventListener("click", () => saveForm("Complete"));
  $("copyTicketBtn").addEventListener("click", copyFromForm);
  $("deleteFormBtn").addEventListener("click", () => deleteNote(activeNoteId));
  $("editDetailBtn").addEventListener("click", () => editNote(activeNoteId));
  $("copyTicketDetailBtn").addEventListener("click", () => copyNote(activeNoteId, "ticket"));
  $("copyClientDetailBtn").addEventListener("click", () => copyNote(activeNoteId, "client"));
  $("duplicateDetailBtn").addEventListener("click", () => duplicateNote(activeNoteId));
  $("deleteDetailBtn").addEventListener("click", () => deleteNote(activeNoteId));
  $("exportBtn").addEventListener("click", exportAll);
  $("clearBtn").addEventListener("click", clearAllData);
  ["searchInput", "contextFilter", "categoryFilter", "statusFilter", "priorityFilter"].forEach((id) => $(id).addEventListener("input", renderList));
  document.querySelectorAll("input, textarea").forEach((input) => input.addEventListener("focus", () => activeSpeechField = input));
}

function setupSpeech() {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRecognition) return;
  const recognition = new SpeechRecognition();
  recognition.continuous = false;
  recognition.interimResults = false;
  recognition.lang = navigator.language || "en-AU";
  $("speechControls").classList.remove("hidden");
  recognition.addEventListener("result", (event) => {
    const transcript = event.results[0][0].transcript;
    const target = activeSpeechField || fields.issue;
    target.value = `${target.value}${target.value && !target.value.endsWith(" ") ? " " : ""}${transcript}`;
    $("micStatus").textContent = "Dictation inserted.";
  });
  recognition.addEventListener("end", () => $("micBtn").disabled = false);
  recognition.addEventListener("error", () => {
    $("micBtn").disabled = false;
    $("micStatus").textContent = "Dictation unavailable.";
  });
  $("micBtn").addEventListener("click", () => {
    $("micBtn").disabled = true;
    $("micStatus").textContent = "Listening...";
    recognition.start();
  });
}

function newNote() {
  activeNoteId = "";
  populateForm(blankNote());
  $("formTitle").textContent = "New Field Note";
  showView("formView");
  fields.title.focus();
}

function blankNote() {
  const now = new Date().toISOString();
  return { id: crypto.randomUUID(), createdAt: now, updatedAt: now, context: "Avance", title: "", category: "Other", priority: "Normal", status: "Draft", manualLocation: "", issue: "", checks: "", changes: "", result: "", followUp: "", tags: "", copiedAt: "" };
}

function editNote(id) {
  const note = findNote(id);
  if (!note) return;
  activeNoteId = id;
  populateForm(note);
  $("formTitle").textContent = "Edit Field Note";
  showView("formView");
}

function populateForm(note) {
  fields.noteId.value = note.id;
  fields.context.value = note.context || "Avance";
  fields.title.value = note.title || "";
  fields.category.value = note.category || "Other";
  fields.priority.value = note.priority || "Normal";
  fields.status.value = note.status || "Draft";
  fields.manualLocation.value = note.manualLocation || "";
  fields.issue.value = note.issue || "";
  fields.checks.value = note.checks || "";
  fields.changes.value = note.changes || "";
  fields.result.value = note.result || "";
  fields.followUp.value = note.followUp || "";
  fields.tags.value = note.tags || "";
}

function readForm(statusOverride) {
  const existing = findNote(fields.noteId.value);
  const now = new Date().toISOString();
  return { id: fields.noteId.value || crypto.randomUUID(), createdAt: existing?.createdAt || now, updatedAt: now, context: fields.context.value, title: fields.title.value.trim(), category: fields.category.value, priority: fields.priority.value, status: statusOverride || fields.status.value, manualLocation: fields.manualLocation.value.trim(), issue: fields.issue.value.trim(), checks: fields.checks.value.trim(), changes: fields.changes.value.trim(), result: fields.result.value.trim(), followUp: fields.followUp.value.trim(), tags: fields.tags.value.trim(), copiedAt: existing?.copiedAt || "" };
}

function saveForm(statusOverride) {
  if (!$("noteForm").reportValidity()) return null;
  const note = readForm(statusOverride);
  const index = notes.findIndex((item) => item.id === note.id);
  if (index >= 0) notes[index] = note;
  else notes.unshift(note);
  activeNoteId = note.id;
  saveNotes(notes);
  showToast(statusOverride === "Complete" ? "Note marked complete." : "Draft saved.");
  renderDetail(note.id);
  return note;
}

function copyFromForm() {
  const note = saveForm(fields.status.value);
  if (note) copyNote(note.id, "ticket");
}

async function copyNote(id, type) {
  const note = findNote(id);
  if (!note) return;
  try {
    await navigator.clipboard.writeText(type === "client" ? buildClientSummary(note) : buildTicketNote(note));
  } catch {
    showToast("Clipboard permission was not available.");
    return;
  }
  note.copiedAt = new Date().toISOString();
  saveNotes(notes);
  renderList();
  showToast(type === "client" ? "Client summary copied." : "Ticket note copied.");
}

function duplicateNote(id) {
  const source = findNote(id);
  if (!source) return;
  const now = new Date().toISOString();
  const copy = { ...source, id: crypto.randomUUID(), title: `${source.title} copy`, status: "Draft", createdAt: now, updatedAt: now, copiedAt: "" };
  notes.unshift(copy);
  saveNotes(notes);
  editNote(copy.id);
  showToast("Note duplicated.");
}

function deleteNote(id) {
  if (!id) return showList();
  if (!confirm("Delete this note? This cannot be undone.")) return;
  notes = notes.filter((note) => note.id !== id);
  saveNotes(notes);
  activeNoteId = "";
  showToast("Note deleted.");
  showList();
}

function renderList() {
  const query = $("searchInput").value.trim().toLowerCase();
  const filtered = notes
    .filter((note) => match($("contextFilter").value, "All contexts", note.context))
    .filter((note) => match($("categoryFilter").value, "All categories", note.category))
    .filter((note) => match($("statusFilter").value, "All statuses", note.status))
    .filter((note) => match($("priorityFilter").value, "All priorities", note.priority))
    .filter((note) => matchesSearch(note, query))
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
  $("notesList").innerHTML = filtered.length ? filtered.map(noteCard).join("") : `<div class="empty-state">No notes match the current search or filters.</div>`;
  document.querySelectorAll("[data-open-note]").forEach((button) => button.addEventListener("click", () => renderDetail(button.dataset.openNote)));
}

function match(filterValue, allLabel, noteValue) {
  return filterValue === allLabel || filterValue === noteValue;
}

function matchesSearch(note, query) {
  if (!query) return true;
  return [note.title, note.issue, note.checks, note.changes, note.result, note.followUp, note.tags, note.manualLocation].join(" ").toLowerCase().includes(query);
}

function noteCard(note) {
  return `<article class="note-card"><div class="note-card-main"><div><h3>${escapeHtml(note.title || "Untitled note")}</h3><p>${escapeHtml(note.issue || note.result || note.followUp || "No preview text yet.")}</p></div><button class="secondary-button" data-open-note="${escapeHtml(note.id)}">Open</button></div><div class="meta-row"><span>${escapeHtml(note.context)}</span><span>${escapeHtml(note.category)}</span><span class="status ${className(note.status)}">${escapeHtml(note.status)}</span><span class="priority ${className(note.priority)}">${escapeHtml(note.priority)}</span><span>${formatDateTime(note.createdAt)}</span></div></article>`;
}

function renderDetail(id) {
  const note = findNote(id);
  if (!note) return;
  activeNoteId = id;
  $("detailTitle").textContent = note.title || "Untitled note";
  $("noteDetail").innerHTML = `<div class="detail-meta"><span><strong>Context:</strong> ${escapeHtml(note.context)}</span><span><strong>Category:</strong> ${escapeHtml(note.category)}</span><span><strong>Priority:</strong> ${escapeHtml(note.priority)}</span><span><strong>Status:</strong> ${escapeHtml(note.status)}</span><span><strong>Created:</strong> ${formatDateTime(note.createdAt)}</span><span><strong>Updated:</strong> ${formatDateTime(note.updatedAt)}</span>${note.manualLocation ? `<span><strong>Location:</strong> ${escapeHtml(note.manualLocation)}</span>` : ""}${note.copiedAt ? `<span><strong>Copied:</strong> ${formatDateTime(note.copiedAt)}</span>` : ""}</div>${block("Issue", note.issue)}${block("Checks performed", note.checks)}${block("Changes / actions taken", note.changes)}${block("Result", note.result)}${block("Follow-up / watch items", note.followUp)}${note.tags ? block("Tags", note.tags) : ""}`;
  showView("detailView");
}

function block(title, value) {
  return `<section class="detail-block"><h3>${escapeHtml(title)}</h3><p>${escapeHtml(value || "")}</p></section>`;
}

function exportAll() {
  if (!notes.length) return showToast("There are no notes to export.");
  const url = URL.createObjectURL(new Blob([buildExportText(notes)], { type: "text/plain" }));
  const link = document.createElement("a");
  link.href = url;
  link.download = `field-notes-${new Date().toISOString().slice(0, 10)}.txt`;
  link.click();
  URL.revokeObjectURL(url);
  showToast("Export started.");
}

function clearAllData() {
  if (!confirm("Clear all saved notes from this browser? This cannot be undone.")) return;
  notes = [];
  clearNotes();
  renderList();
  showToast("All local notes cleared.");
}

function showList() {
  renderList();
  showView("listView");
}

function showView(id) {
  document.querySelectorAll(".view").forEach((view) => view.classList.add("hidden"));
  $(id).classList.remove("hidden");
}

function findNote(id) {
  return notes.find((note) => note.id === id);
}

function className(value) {
  return value.toLowerCase().replace(/\s+/g, "-");
}

function showToast(message) {
  $("toast").textContent = message;
  $("toast").classList.add("show");
  window.setTimeout(() => $("toast").classList.remove("show"), 2400);
}

function escapeHtml(value) {
  return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#039;");
}

init();
