  <header class="app-header"><div><p class="eyebrow">Local IT incident logger</p><h1>FieldNotesApp</h1></div><button id="newNoteTop" class="primary-button">New Note</button></header>
  <main class="app-shell">
    <section class="privacy-note" aria-label="Privacy note">Local-only: notes are saved in this browser. Avoid storing passwords, student details, client secrets, or sensitive personal information.</section>
    <section id="listView" class="view">
      <div class="toolbar"><label class="search-field"><span>Search notes</span><input id="searchInput" type="search" placeholder="Search issue, checks, tags, location..." autocomplete="off"></label><div class="toolbar-actions"><button id="newNoteBtn" class="primary-button">New Note</button><button id="exportBtn" class="secondary-button">Export All</button><button id="clearBtn" class="danger-button">Clear Demo/All Data</button></div></div>
      <div class="filters" aria-label="Note filters"><label><span>Context</span><select id="contextFilter"></select></label><label><span>Category</span><select id="categoryFilter"></select></label><label><span>Status</span><select id="statusFilter"></select></label><label><span>Priority</span><select id="priorityFilter"></select></label></div>
      <div id="notesList" class="notes-list" aria-live="polite"></div>
    </section>
    <section id="formView" class="view hidden">
      <div class="section-heading"><div><p class="eyebrow">Capture note</p><h2 id="formTitle">New Field Note</h2></div><button id="backFromForm" class="secondary-button">Back to list</button></div>
      <form id="noteForm" class="note-form"><input id="noteId" type="hidden"><div class="form-grid"><label><span>Context</span><select id="context" required></select></label><label><span>Category</span><select id="category"></select></label><label><span>Priority</span><select id="priority"></select></label><label><span>Status</span><select id="status"></select></label></div><label><span>Title / Issue Summary</span><input id="title" type="text" required placeholder="Short issue summary"></label><label><span>Manual Location / Site / Room / Device</span><input id="manualLocation" type="text" placeholder="Room, site, client, device, or general location"></label><div class="textarea-stack"><label><span>Issue: what happened</span><textarea id="issue" required rows="4"></textarea></label><label><span>Checks: what I checked/tested</span><textarea id="checks" required rows="4"></textarea></label><label><span>Changes: what I changed/tried</span><textarea id="changes" required rows="4"></textarea></label><label><span>Result</span><textarea id="result" required rows="4"></textarea></label><label><span>Follow-up needed</span><textarea id="followUp" required rows="3"></textarea></label></div><label><span>Tags</span><input id="tags" type="text" placeholder="comma-separated tags"></label><div id="speechControls" class="speech-controls hidden"><button id="micBtn" type="button" class="secondary-button">Dictate into active field</button><span id="micStatus" aria-live="polite"></span></div><div class="form-actions"><button id="saveDraftBtn" type="button" class="secondary-button">Save Draft</button><button id="markCompleteBtn" type="button" class="primary-button">Mark Complete</button><button id="copyTicketBtn" type="button" class="secondary-button">Copy Ticket Note</button><button id="deleteFormBtn" type="button" class="danger-button">Delete</button></div></form>
    </section>
    <section id="detailView" class="view hidden"><div class="section-heading"><div><p class="eyebrow">Field note</p><h2 id="detailTitle"></h2></div><button id="backFromDetail" class="secondary-button">Back to list</button></div><article id="noteDetail" class="detail-panel"></article><div class="form-actions"><button id="editDetailBtn" class="primary-button">Edit</button><button id="copyTicketDetailBtn" class="secondary-button">Copy Ticket Note</button><button id="copyClientDetailBtn" class="secondary-button">Copy Client Summary</button><button id="duplicateDetailBtn" class="secondary-button">Duplicate Note</button><button id="deleteDetailBtn" class="danger-button">Delete</button></div></section>
  </main>
